<script lang="ts">
 import {onMount,onDestroy,untrack} from 'svelte';
 import {invoke} from '@tauri-apps/api/core';
 import MailRecipient from './MailRecipient.svelte';
 import {X,Clock,Users,MapPin} from 'lucide-svelte';
 import MeetingDateTime from './MeetingDateTime.svelte';
 import {meetingDuration,defaultMeetingEnd} from './meeting-time';
 import MailConfirm from './MailConfirm.svelte';
 import type {CalendarEvent} from './calendar';
 let {ownId,onClose,onCreated,detailsOpen,onOpenDetails,onCloseDetails}:{ownId:string;onClose:()=>void;onCreated:(event:CalendarEvent,warning?:string)=>void;detailsOpen:boolean;onOpenDetails:()=>void;onCloseDetails:()=>void}=$props();
 type Room={emailAddress:string;displayName:string;capacity?:number;building?:string;floorLabel?:string};
 const key=untrack(()=>JSON.stringify(['taut-meeting-draft',ownId]));
 let subject=$state(''),description=$state(''),start=$state(''),end=$state(''),attendees=$state(''),room=$state<Room|null>(null),transactionId=$state(crypto.randomUUID()),attempted=$state(false);
 let endManual=$state(false);
 let online=$state(false),onlineSupported=$state(false),onlineChecking=$state(true),onlineError=$state('');
 let rooms=$state<Room[]>([]),next=$state<string|null>(null),query=$state(''),roomBusy=$state(false),roomError=$state(''),busy=$state(false),error=$state(''),review=$state(false),discard=$state(false),ready=$state(false),storageError=$state('');
 let availability=$state<{scheduleId:string;availabilityView?:string;error?:unknown}[]>([]),checked=$state('');let alive=true;
 const zone=Intl.DateTimeFormat().resolvedOptions().timeZone;
 const emails=$derived(attendees.split(/[;,\n]/).map(x=>x.trim()).filter(Boolean));
 const timeValid=$derived(!!start&&!!end&&Number.isFinite(new Date(start).getTime())&&new Date(end)>new Date(start));
 const reason=$derived(online&&(onlineChecking||!onlineSupported)?'Teams meeting support must be confirmed, or turn off Teams meeting.':!subject.trim()?'Add a subject.':!timeValid?'Choose an end time after the start.':emails.length>20?'Use at most 20 attendees.':emails.some(x=>!/^\S+@[^\s@]+$/.test(x))?'Check attendee email addresses.':new Set([...emails,...(room?[room.emailAddress]:[])].map(x=>x.toLowerCase())).size!==emails.length+(room?1:0)?'Remove duplicate attendees and room addresses.':attempted?'Creation was attempted. Check Calendar or Outlook before starting another meeting.':storageError);
 const fingerprint=$derived(JSON.stringify([start,end,emails,room?.emailAddress]));
 const filtered=$derived(rooms.filter(r=>`${r.displayName} ${r.emailAddress} ${r.building??''}`.toLowerCase().includes(query.toLowerCase())));
 onMount(()=>{try{const raw=localStorage.getItem(key);if(raw){const d=JSON.parse(raw);online=d.online===true;subject=d.subject??'';description=d.description??'';start=d.start??'';end=d.end??'';endManual=typeof d.endManual==='boolean'?d.endManual:!!end;attendees=d.attendees??'';room=d.room??null;transactionId=d.transactionId??crypto.randomUUID();attempted=d.attempted===true;}}catch{storageError='Saved draft could not be loaded. Close and try again.';}ready=true;void loadRooms();void checkOnline();});
 onDestroy(()=>alive=false);
 function snapshot(){return {subject,description,start,end,attendees,room,transactionId,attempted,online,endManual};}
 $effect(()=>{if(ready){const value=JSON.stringify(snapshot());try{localStorage.setItem(key,value);}catch{storageError='Draft could not be saved on this device. Free storage before sending.';}}});
 function changeStart(value:string){start=value;if(!endManual){const suggested=defaultMeetingEnd(value,meetingDuration(localStorage));if(suggested)end=suggested;}}
 const availabilityReason=$derived(!timeValid?'Set a valid start and end time to check availability.':emails.length+(room?1:0)===0?'Add an attendee or room to check availability. You can still create a meeting without either.':emails.length+(room?1:0)>20?'Check at most 20 people and rooms at once.':'');
 async function checkOnline(){onlineChecking=true;onlineError='';try{const supported=await invoke<boolean>('calendar_online_support');if(alive)onlineSupported=supported;}catch{if(alive){onlineSupported=false;onlineError='Teams meeting support could not be checked.';}}finally{if(alive)onlineChecking=false;}}
 async function loadRooms(more=false){roomBusy=true;roomError='';try{const result=await invoke<{value:Room[];next:string|null}>('calendar_rooms',{next:more?next:null});if(!alive)return;rooms=[...new Map([...(more?rooms:[]),...result.value.filter(r=>r.emailAddress)].map(r=>[r.emailAddress,r])).values()];next=result.next;}catch(e){if(alive)roomError=String(e);}finally{if(alive)roomBusy=false;}}
 async function check(){if(!timeValid||busy)return;const addresses=[...emails,...(room?[room.emailAddress]:[])];if(!addresses.length){error='Add attendees or choose a room to check availability.';return;}if(addresses.length>20){error='Check at most 20 people and rooms at once.';return;}const version=fingerprint;onOpenDetails();busy=true;error='';try{const result=await invoke<typeof availability>('calendar_availability',{addresses,start:new Date(start).toISOString(),end:new Date(end).toISOString()});if(alive&&version===fingerprint){availability=result;checked=version;}}catch(e){if(alive)error=String(e);}finally{if(alive)busy=false;}}
 async function send(){if(reason||busy)return;review=false;busy=true;error='';try{attempted=true;localStorage.setItem(key,JSON.stringify(snapshot()));}catch{attempted=false;error='Could not save the send attempt. Nothing was sent.';busy=false;return;}
 try{const result=await invoke<{status:string;event?:CalendarEvent;error?:string;warning?:string}>('calendar_create',{ownId,draft:{transactionId,subject,description,online,start:new Date(start).toISOString(),end:new Date(end).toISOString(),attendees:emails,room:room?{emailAddress:room.emailAddress,displayName:room.displayName}:null}});if(!alive)return;if(result.status==='created'&&result.event){localStorage.removeItem(key);ready=false;onCreated(result.event,result.warning);}else{if(result.status==='notSent'){attempted=false;localStorage.setItem(key,JSON.stringify(snapshot()));}error=result.error??'Creation unconfirmed. Check Outlook before another attempt.';}}catch(e){if(alive)error=String(e);}finally{if(alive)busy=false;}}
</script>
<section class="meeting-composer" aria-label="New meeting"><header><div><div class="eyebrow">A LITTLE ROOM TOGETHER</div><h2>New meeting</h2><p>Draft saved on this device · invitations send only after review</p></div><button disabled={busy} onclick={onClose}>Save & close</button></header>
<div class="fields"><fieldset disabled={busy||attempted}><label>Subject<input maxlength="255" bind:value={subject} placeholder="What are we getting together for?"/></label><div class="times"><MeetingDateTime label="Start" value={start} onChange={changeStart}/><MeetingDateTime label="End" value={end} onChange={value=>{end=value;endManual=true;}}/></div><small>Times are in {zone}. This is a single meeting.</small><div class="attendee-input"><MailRecipient label="Attendees" value={attendees} {ownId} onFocus={()=>{}} onChange={value=>attendees=value}/><small>Type a coworker’s name or enter addresses separated by semicolons.</small></div><section class="online-option" aria-label="Online meeting"><label class="online-toggle"><input type="checkbox" bind:checked={online} disabled={!online&&(onlineChecking||!onlineSupported)}/>Teams meeting</label>{#if onlineChecking}<small>Checking Teams meeting support…</small>{:else if onlineError}<small role="alert">{onlineError}</small><button type="button" onclick={checkOnline}>Retry Teams support</button>{:else if !onlineSupported}<small>This calendar does not support creating Teams meetings.</small>{:else}<small>{online?'Microsoft 365 will add Teams join details when this meeting is created.':'Add a Teams join link for remote attendees.'}</small>{/if}</section><label>Description<textarea rows="5" bind:value={description}></textarea></label></fieldset>
<section class="room-picker"><p>Rooms are optional. Choose one for an in-person or hybrid meeting; Teams attendees can join remotely.</p><div class="eyebrow">MAKE ROOM</div><h3>{room?room.displayName:'Choose a room (optional)'}</h3>{#if room}<p>{room.emailAddress} · confirmation required from the room</p><button disabled={busy||attempted} onclick={()=>room=null}>Remove room</button>{/if}<label>Find a room<input type="search" bind:value={query} placeholder="Name, building or email"/></label>{#if roomError}<p role="alert">{roomError}</p><button disabled={roomBusy} onclick={()=>loadRooms()}>Retry rooms</button>{/if}<div class="rooms">{#each filtered as r (r.emailAddress)}<button class:chosen={room?.emailAddress===r.emailAddress} disabled={busy||attempted} onclick={()=>room=r}><strong>{r.displayName}</strong><small>{r.emailAddress}</small><small>{[r.building,r.floorLabel,r.capacity!=null?`${r.capacity} seats`:''].filter(Boolean).join(' · ')}</small></button>{/each}</div>{#if roomBusy}<p role="status">Loading rooms…</p>{:else if !rooms.length&&!roomError}<p>No rooms returned. You can still create a meeting without a room.</p>{/if}{#if next}<button disabled={roomBusy} onclick={()=>loadRooms(true)}>Load more rooms</button>{/if}</section>
{#if !detailsOpen}<button onclick={onOpenDetails}>Show meeting summary</button><small>See the meeting summary and availability in the details panel.</small>{/if}
{#if error}<p role="alert">{error}</p>{/if}{#if reason}<p class="reason" role="status">{reason}</p>{/if}<footer><button disabled={busy} onclick={()=>discard=true}>Discard draft</button> <button class="primary" disabled={busy||!!reason} onclick={()=>review=true}>{busy?'Creating…':'Review meeting'}</button></footer></div></section>
{#if detailsOpen}<aside class="meeting-summary" aria-label="Meeting summary"><header><div><div class="eyebrow">TAKING SHAPE</div><h2>Meeting summary</h2></div><button aria-label="Close meeting summary" onclick={onCloseDetails}><X size={18}/></button></header><div class="summary-scroll"><h3>{subject.trim()||'Your next get-together'}</h3><section><h4><Clock size={16}/> When</h4>{#if timeValid}<p>{new Date(start).toLocaleString()}<br/>to {new Date(end).toLocaleString()}</p>{:else}<p>Choose a start and end time.</p>{/if}<small>{zone} · Single meeting</small></section><section><h4>Online meeting</h4><p>{online?'Teams meeting — join details requested on creation':'No Teams meeting requested'}</p></section><section><h4><Users size={16}/> People · {emails.length}</h4>{#each emails as email}<p class="person-address">{email}</p>{:else}<p>Only you so far.</p>{/each}</section><section><h4><MapPin size={16}/> Room</h4>{#if room}<p><strong>{room.displayName}</strong><br/>{room.emailAddress}</p><small>{[room.building,room.floorLabel,room.capacity!=null?`${room.capacity} seats`:''].filter(Boolean).join(' · ')}</small><p class="booking-note">Requested when invitations are sent. Booking requires the room’s acceptance.</p>{:else}<p>No room selected. A room is optional.</p>{/if}</section><section><div class="eyebrow">AVAILABILITY</div>{#if checked===fingerprint}{#each availability as item}<div class="availability"><strong>{item.scheduleId===room?.emailAddress?room.displayName:item.scheduleId}</strong><span class:free={!item.error&&!!item.availabilityView&&/^[0]+$/.test(item.availabilityView)}>{item.error||!item.availabilityView?'Availability unknown':/^[0]+$/.test(item.availabilityView)?'Free at the requested time':'Conflict or tentative booking'}</span></div>{:else}<p>No availability returned.</p>{/each}{:else if checked}<p class="booking-note">Time or attendees changed. Check availability again.</p>{:else}<p>Check your selected time for people and rooms.</p>{/if}<button disabled={busy||!!availabilityReason||attempted} onclick={check}>{busy?'Checking…':'Check availability'}</button>{#if availabilityReason}<p><small>{availabilityReason}</small></p>{/if}<p><small>Availability is advisory. Exchange applies each room’s booking and approval policies.</small></p></section></div></aside>{/if}
{#if discard}<MailConfirm title="Discard meeting draft?" confirmLabel="Discard draft" onClose={()=>discard=false} onConfirm={()=>{localStorage.removeItem(key);ready=false;onClose();}}><p>This removes the local draft only.</p>{#if attempted}<p>Creation was attempted. Check Calendar or Outlook before creating a replacement; discarding this draft does not cancel an event.</p>{/if}</MailConfirm>{/if}
{#if review}<MailConfirm title="Create this meeting?" confirmLabel="Create & send invitations" onClose={()=>review=false} onConfirm={send}><p><strong>{subject}</strong></p><p>{new Date(start).toLocaleString()} – {new Date(end).toLocaleString()} ({zone})</p><p>{online?'Teams meeting: Microsoft 365 will generate the join details.':'No Teams meeting requested.'}</p><p>Attendees: {emails.join('; ')||'Only you'}</p>{#if room}<p>Room requested: <strong>{room.displayName}</strong> ({room.emailAddress}). It is not booked until the room accepts.</p>{/if}<p>This creates an event on your calendar and sends invitations to the listed people and room.</p></MailConfirm>{/if}
<style>
.online-option{display:grid;gap:10px}.online-toggle{display:flex;align-items:center;gap:10px}.online-toggle input{width:auto}
.meeting-composer{flex:1;min-width:0;overflow:auto;color:var(--text-primary)}header{display:flex;justify-content:space-between;gap:20px;padding:28px;background:var(--surface-panel);border-bottom:1px solid var(--border)}h2{margin:10px 0;font-size:28px}.eyebrow{font-size:10px;letter-spacing:2px;color:var(--accent);font-weight:700}p,small{line-height:1.7}header p,small{color:var(--text-secondary)}.fields{max-width:900px;margin:auto;padding:28px;display:grid;gap:18px}fieldset{border:0;padding:0;display:grid;gap:18px;min-width:0}label{display:grid;gap:8px;font-size:13px}input,textarea,button{font:inherit;color:var(--text-primary);border:1px solid var(--border-strong);border-radius:9px;background:var(--surface-panel);padding:11px 14px}input,textarea{width:100%;box-sizing:border-box}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}.times{display:grid;grid-template-columns:1fr 1fr;gap:18px}.room-picker{border:1px solid var(--border);border-radius:14px;padding:22px;background:var(--surface-panel)}.room-picker label{margin:18px 0}.rooms{display:grid;gap:8px;max-height:250px;overflow:auto}.rooms button{text-align:left;display:grid;gap:4px}.chosen{border-color:var(--accent);background:var(--accent-soft)}.primary{background:var(--accent);color:var(--text-on-accent)}[role=alert]{color:var(--danger-text)}.reason{padding:12px;border-left:3px solid var(--accent);background:var(--accent-soft)}button:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid var(--accent);outline-offset:3px}header button{align-self:center;white-space:nowrap}
.attendee-input :global(.recipient){display:block;margin:0}.attendee-input :global(.recipient label){display:block;margin-bottom:8px}.attendee-input :global(.recipient input){font-size:14px;padding:11px 14px}.meeting-summary{width:340px;max-width:40%;flex:none;display:flex;flex-direction:column;background:var(--surface-panel);border-left:1px solid var(--border);min-height:0}.meeting-summary header{padding:24px;align-items:center}.meeting-summary h2{font-size:20px}.meeting-summary header button{padding:7px;display:grid;place-items:center}.summary-scroll{padding:24px;overflow:auto;min-height:0}.summary-scroll h3{font-size:21px;line-height:1.4;overflow-wrap:anywhere;margin:0 0 20px}.summary-scroll section{padding:20px 0;border-top:1px solid var(--border)}h4{display:flex;gap:9px;align-items:center;margin:0;color:var(--accent);font-size:12px}.summary-scroll p{font-size:13px;overflow-wrap:anywhere}.booking-note{border-left:2px solid var(--accent);padding-left:12px;color:var(--text-secondary)}.availability{display:grid;gap:7px;padding:16px 0;font-size:12px;overflow-wrap:anywhere}.availability span{color:var(--accent)}.availability .free{color:var(--text-secondary)}@media(max-width:1000px){.meeting-summary{width:280px}.fields{padding:20px}.times{grid-template-columns:1fr}}
</style>
